export type CalendarView = 'month' | 'week' | 'day';

export interface CalendarDefaults {
  vormerkbuch: CalendarView;
  arbeitskalender: CalendarView;
}

export enum UserRole {
  SUPERADMIN = 'SUPERADMIN',
  ADMIN = 'ADMIN',
  MEMBER = 'MEMBER',
  APPLICANT = 'APPLICANT'
}

export interface UserPreferences {
  calendarDefaults?: Partial<CalendarDefaults>;
  showCancelledReservations?: boolean;
  seenChangelogIds?: string[]; // IDs gelesener Einträge unter „Neuigkeiten“
  uiVersion?: 'v1' | 'v2'; // gewählte Oberfläche (v2 nur, wenn freigeschaltet; siehe docs/ux-audit-v2.md)
  v2TourSeen?: boolean; // Einführung der neuen Oberfläche abgeschlossen oder übersprungen
}

export type ActivityEntityType = 'reservation' | 'workHour' | 'boat' | 'member' | 'system';

export type ActivityType =
  | 'reservation.created'
  | 'reservation.status_changed'
  | 'reservation.deleted'
  | 'workHour.created'
  | 'workHour.updated'
  | 'workHour.deleted'
  | 'boat.created'
  | 'boat.updated'
  | 'boat.deleted'
  | 'member.created'
  | 'member.updated'
  | 'member.deactivated'
  | 'member.deleted'
  | 'season.backfill'
  | 'season.activated'
  | 'season.next_opened'
  | 'season.started';

export interface ActivityLogEntry {
  id: string;
  type: ActivityType;
  entityId: string;
  entityType: ActivityEntityType;
  actorId: string;
  actorName: string;
  timestamp: Date;
  details: Record<string, unknown>;
}

export interface User {
  id: string;
  email: string;
  displayName: string;
  deactivated?: boolean;
  roles: UserRole[];
  feesPaid: boolean;
  skipHours?: boolean;
  onboardingState?: 'not_started' | 'skipped' | 'completed';
  preferences?: UserPreferences;
  createdAt: Date;
  updatedAt: Date;
  emailVerified?: boolean;
  lastLoginAt?: Date;
}

export interface Boat {
  id: string;
  name: string;
  description?: string;
  bootswart?: string; // User ID of Bootswart
  bootswart2?: string; // User ID of second Bootswart
  requiresApproval: boolean; // Whether reservations need bootswart approval
  blocked: boolean; // Whether the boat is currently blocked
  color: string; // CSS color value
  createdAt: Date;
  updatedAt: Date;
}

export interface WorkAppointment {
  id: string;
  title: string;
  description: string;
  startTime: Date;
  endTime: Date;
  boatId?: string;
  maxParticipants?: number;
  participants: WorkParticipant[];
  supplies: Supply[];
  private?: boolean;
  createdByUserId?: string;
  createdByUserName?: string;
  // Gesetzt, wenn ein Bootswart einen Termin für ein fremdes Boot anlegt: eigenes Boot als Nachweis der Bootswart-Rolle (Firestore-Regeln)
  createdAsBootswartOfBoatId?: string;
  createdAt: Date;
  updatedAt: Date;
}

export type Supply = string;

export interface WorkParticipant {
  userId: string;
  userName: string;
  status: 'pending' | 'confirmed' | 'declined';
  createdAt: Date;
  updatedAt: Date;
  startTime?: Date;
  endTime?: Date;
  confirmedByUserId?: string;
  confirmedByUserName?: string;
  confirmedAt?: Date;
  season?: number; // Saison (Jahreszahl), für die diese Stunden zählen; fehlt bei Alt-Einträgen
  seasonManual?: boolean; // true, wenn das Mitglied bewusst eine andere als die Standard-Saison gewählt hat
}

export type ReservationStatus = 'draft' | 'pending' | 'approved' | 'rejected' | 'cancelled';

export type ReservationVisibility = 'private' | 'public';

export interface PublicReservationDetails {
  freeSeatsText?: string;
}

export interface BoatReservation {
  id: string;
  boatId: string;
  userId: string;
  userName: string;
  title: string;
  description?: string;
  startTime: Date;
  endTime: Date;
  status: ReservationStatus;
  visibility: ReservationVisibility;
  publicDetails?: PublicReservationDetails;
  eligibilitySnapshot?: {
    feesPaid: boolean;
    skipHours: boolean;
    workHoursMet: boolean;
  };
  createdAt: Date;
  updatedAt: Date;
}

export interface PublicBoatReservation {
  id: string;
  boatId: string;
  boatName: string;
  title: string;
  startTime: Date;
  endTime: Date;
  visibility: ReservationVisibility;
  reservationStatus: Exclude<ReservationStatus, 'draft' | 'rejected' | 'cancelled'>;
  freeSeatsText?: string;
  updatedAt: Date;
}

export interface SystemConfig {
  id: string;
  yearChangeDate: Date; // Stored with year 2000, only month and day are relevant. Nach Aktivierung des Saisonmodells nur noch Fallback für Alt-Einträge.
  workHourThreshold: number;
  // Saisonmodell (siehe docs/arbeitsstunden-logik.md). Ohne `seasonModelActivatedAt` gilt ausschließlich `yearChangeDate`.
  currentSeason?: number; // Saison, deren Stunden für die Reservierungsberechtigung zählen
  nextSeasonOpen?: boolean; // Buchung für currentSeason + 1 möglich (Überlappungsphase)
  nextSeasonOpenedAt?: Date;
  currentSeasonStartedAt?: Date;
  seasonBackfillAt?: Date; // Zeitpunkt des letzten Backfills der Saisonzuordnung
  seasonModelActivatedAt?: Date;
  calendarDefaults?: CalendarDefaults;
  featureFlags?: {
    enableMemberCreation?: boolean;
    uiV2ForMembers?: boolean; // neue Oberfläche (v2) auch für Mitglieder freigeschaltet; Admins dürfen sie immer testen
  };
  createdAt?: Date;
  updatedAt?: Date;
}
